@dataclass
class TaskContext:
    """封装一次平台任务执行的全部上下文。"""
    platform_task_id: int = 0          # 平台 Task PK
    task_id: str = ''                  # 如 proj-xxx-P1-1
    title: str = ''
    spec_document: str = ''            # 完整规格文档（不截断）
    priority: int = 5
    depends_on: list = field(default_factory=list)
    task_workspace: Path = None        # 中间产物: workspace/projects/{proj}/tasks/{task_id}/
    repo_docs_dir: Path = None         # 最终产物: workspace/projects/{proj}/repos/{仓库名}/docs/
    is_task_zero: bool = False         # 是否为 Task 0
    phase_index: int = 0               # 阶段序号
    project_id: str = ''               # 项目标识
    task_type: str = 'general'         # doc / code / analysis / general
    template_ref: str = ''             # 关联模板名称
    required_skills: list = field(default_factory=list)
    progress_callback: Callable = None # (progress: int, phase: str, message: str) -> None

    @staticmethod
    def from_payload(payload: dict, home: str) -> 'TaskContext':
        """从 platform.task.assign 消息构造 TaskContext。"""
        task_id = payload.get('task_id', '')
        platform_task_id = payload.get('platform_task_id', 0)
        project_id, phase_index = _parse_task_id(task_id)
        is_task_zero = task_id.endswith('-0')

        # 任务类型推断
        title = payload.get('title', '')
        template_ref = payload.get('template_ref', '')
        required_skills = payload.get('required_skills', [])
        task_type = _infer_task_type(title, template_ref, required_skills)

        # 分层工作空间路径
        proj_ws = Path(home) / 'workspace' / 'projects' / project_id
        task_ws = proj_ws / 'tasks' / task_id
        repo_name = payload.get('repo_name') or project_id
        repo_docs = proj_ws / 'repos' / repo_name / 'docs'

        ctx = TaskContext(
            platform_task_id=platform_task_id,
            task_id=task_id,
            title=title,
            spec_document=payload.get('spec_document', ''),
            priority=payload.get('priority', 5),
            depends_on=payload.get('depends_on', []),
            task_workspace=task_ws,
            repo_docs_dir=repo_docs,
            is_task_zero=is_task_zero,
            phase_index=phase_index,
            project_id=project_id,
            task_type=task_type,
            template_ref=template_ref,
            required_skills=required_skills,
        )
        return ctx

    def ensure_dirs(self):
        """创建任务工作空间目录。"""
        if self.task_workspace:
            self.task_workspace.mkdir(parents=True, exist_ok=True)
            (self.task_workspace / 'scratch').mkdir(exist_ok=True)
            (self.task_workspace / 'artifacts').mkdir(exist_ok=True)
        if self.repo_docs_dir:
            self.repo_docs_dir.mkdir(parents=True, exist_ok=True)

    def report_progress(self, progress: int, phase: str = '',
                        message: str = ''):
        """上报进度（安全调用）。"""
        if self.progress_callback:
            try:
                self.progress_callback(progress, phase, message)
            except Exception:
                logger.debug('进度上报失败', exc_info=True)


# ─────────────────────────────────────────
# 辅助函数
# ─────────────────────────────────────────

def _parse_task_id(task_id: str):
    """从 task_id 解析 project_id 和 phase_index。

    格式: {project_id}-P{phase}-{seq}
    例如: proj-abc-P1-3 → ('proj-abc', 1)
    """
    m = re.match(r'^(.+)-P(\d+)-\d+$', task_id)
    if m:
        return m.group(1), int(m.group(2))
    # Task 0 格式: {project_id}-P{phase}-0
    m = re.match(r'^(.+)-P(\d+)-0$', task_id)
    if m:
        return m.group(1), int(m.group(2))
    return task_id, 0


def _infer_task_type(title: str, template_ref: str,
                     required_skills: list) -> str:
    """从标题/模板/技能推断任务类型。"""
    text = (title + ' ' + template_ref).lower()
    skills_lower = [s.lower() for s in (required_skills or [])]

    # 代码编写类
    code_keywords = ['代码', '编码', '接口', '模块', '开发', '编程', '函数',
                     'code', 'api', 'backend', 'frontend']
    for kw in code_keywords:
        if kw in text or kw in skills_lower:
            return 'code'

    # 文档编写类
    doc_keywords = ['编写', '撰写', '文档', '说明书', '报告', '计划',
                    '规格', '大纲', '模板']
    if template_ref:
        return 'doc'
    for kw in doc_keywords:
        if kw in text:
            return 'doc'

    # 分析类
    analysis_keywords = ['分析', '调研', '评审', '评估', '审查', '测试']
    for kw in analysis_keywords:
        if kw in text:
            return 'analysis'

    return 'general'


