# ─────────────────────────────────────────
# TaskZeroExecutor — Task 0 阶段拆解（队长角色）
# ─────────────────────────────────────────

class TaskZeroExecutor:
    """Task 0 阶段拆解专用执行器（队长角色）。

    职责链：拆解 → 指派 → 上报 → 待命
    """

    def execute(self, ctx: TaskContext, app) -> TaskResult:
        """执行 Task 0 拆解任务。"""
        token_used = 0
        t_start = time.monotonic()

        try:
            # 1. 进度: 已接收
            ctx.report_progress(5, 'received', '任务已接收')

            # 2. 构建拆解提示词
            builder = TaskPromptBuilder()
            system_prompt = builder.build_task_zero_prompt(ctx, app)
            user_msg = ('请对「%s」阶段进行任务拆解并指派执行人。\n\n%s'
                        % (ctx.title or '当前阶段', ctx.spec_document[:2000]))

            ctx.report_progress(15, 'analyzing', '分析阶段模板内容')

            # 3. LLM 多轮调用
            messages = [
                {'role': 'system', 'content': system_prompt},
                {'role': 'user', 'content': user_msg},
            ]
            tool_schemas = app.tools.get_openai_tools_schema()
            max_rounds = min(5, app.config.get('max_tool_rounds', 5))

            ctx.report_progress(40, 'decomposing', 'LLM 正在生成任务拆解')

            reply_content = ''
            for round_idx in range(max_rounds):
                msg = app.llm.chat(
                    messages, tools=tool_schemas or None,
                    skill='task_zero', category='decomposition')

                # 累计 token
                for m in messages:
                    token_used += LLMClient_quick_estimate(
                        m.get('content', ''))

                # 处理工具调用
                tool_calls = msg.get('tool_calls')
                if tool_calls:
                    messages.append(msg)
                    for tc in tool_calls:
                        fn = tc.get('function', {})
                        try:
                            args = json.loads(fn.get('arguments') or '{}')
                        except ValueError:
                            args = {}
                        result = app._exec_tool_call(
                            fn.get('name', ''), args)
                        messages.append({
                            'role': 'tool',
                            'tool_call_id': tc.get('id', ''),
                            'content': json.dumps(
                                result, ensure_ascii=False)[
                                :app.config.get('output_limit', 8000)],
                        })
                    continue

                reply_content = msg.get('content') or ''
                break

            if not reply_content:
                reply_content = '拆解失败：LLM 未返回有效内容'
                return TaskResult(
                    result_document=reply_content,
                    result_status='REVISION_NEEDED',
                    token_used=token_used)

            ctx.report_progress(60, 'assigning', '为任务指派执行人')

            # 4. JSON 解析与验证
            tasks_json = _parse_task_zero_json(reply_content)

            ctx.report_progress(80, 'formatting', '格式化 JSON 输出')

            # 验证（最多 2 次修正重试）
            for retry in range(2):
                if tasks_json:
                    break
                logger.warning('Task 0 JSON 解析失败，第 %d 次修正', retry + 1)
                messages.append({'role': 'assistant', 'content': reply_content})
                messages.append({
                    'role': 'user',
                    'content': ('你的输出无法解析为有效的任务列表 JSON。'
                                '请重新以 ```json 代码块格式输出任务数组。'
                                '每个任务必须包含 title, description, '
                                'suggested_agent_id 字段。')
                })
                msg = app.llm.chat(
                    messages, skill='task_zero', category='decomposition')
                reply_content = msg.get('content') or ''
                tasks_json = _parse_task_zero_json(reply_content)
                token_used += LLMClient_quick_estimate(reply_content)

            ctx.report_progress(90, 'validating', '验证 JSON Schema')

            # 5. 完成
            if tasks_json:
                # 构造格式化的结果文档
                result_doc = _format_task_zero_result(tasks_json)
            else:
                result_doc = reply_content

            ctx.report_progress(100, 'submitting', '提交拆解+指派方案')

            elapsed = time.monotonic() - t_start
            logger.info('Task 0 执行完成: task=%s tasks=%d token=%d 耗时=%.1fs',
                        ctx.task_id, len(tasks_json), token_used, elapsed)

            return TaskResult(
                result_document=result_doc,
                result_status='SUCCESS' if tasks_json else 'REVISION_NEEDED',
                token_used=token_used)

        except Exception as e:
            logger.exception('Task 0 执行异常: %s', ctx.task_id)
            return TaskResult(
                result_document='Task 0 执行失败: %s' % str(e)[:500],
                result_status='BLOCKED',
                token_used=token_used)


# ─────────────────────────────────────────
# TaskExecutor — 常规任务执行（队员角色）
# ─────────────────────────────────────────

class TaskExecutor:
    """常规项目任务执行器（队员角色）。

    根据任务类型分流：
    - doc/analysis/general → 主 Agent 直接执行（LLM 多轮 + 工具调用）
    - code → 委托 SubagentProvider（Qoder/Codex）
    """

    def execute(self, ctx: TaskContext, app) -> TaskResult:
        """执行常规项目任务。"""
        if ctx.task_type == 'code':
            return self._execute_code_task(ctx, app)
        return self._execute_llm_task(ctx, app)

    # ── 文档/分析/通用任务：主 Agent 直接执行 ──

    def _execute_llm_task(self, ctx: TaskContext, app) -> TaskResult:
        """文档/分析类任务 — 主 Agent LLM 多轮 + 工具调用。"""
        token_used = 0
        t_start = time.monotonic()
        progress = 5

        try:
            ctx.report_progress(progress, 'received', '任务已接收')

            # 构建任务感知提示词
            builder = TaskPromptBuilder()
            system_prompt = builder.build_task_system_prompt(ctx, app)

            # 构造用户消息
            user_msg = '请执行以下任务：%s' % ctx.title
            if ctx.spec_document:
                user_msg += '\n\n详细规格请参见任务规格文档。'

            messages = [
                {'role': 'system', 'content': system_prompt},
                {'role': 'user', 'content': user_msg},
            ]
            tool_schemas = app.tools.get_openai_tools_schema()
            max_rounds = app.config.get('max_tool_rounds', 5)

            ctx.report_progress(15, 'executing', '开始执行任务')

            full_reply = ''
            for round_idx in range(max_rounds):
                msg = app.llm.chat(
                    messages, tools=tool_schemas or None,
                    skill='task_exec', category='project')

                for m in messages:
                    token_used += LLMClient_quick_estimate(
                        m.get('content', ''))

                # 处理工具调用
                tool_calls = msg.get('tool_calls')
                if tool_calls:
                    messages.append(msg)
                    for tc in tool_calls:
                        fn = tc.get('function', {})
                        try:
                            args = json.loads(fn.get('arguments') or '{}')
                        except ValueError:
                            args = {}
                        result = app._exec_tool_call(
                            fn.get('name', ''), args)
                        messages.append({
                            'role': 'tool',
                            'tool_call_id': tc.get('id', ''),
                            'content': json.dumps(
                                result, ensure_ascii=False)[
                                :app.config.get('output_limit', 8000)],
                        })
                    # 进度递增
                    progress = min(progress + 12, 80)
                    ctx.report_progress(
                        progress, 'executing',
                        '第 %d 轮工具调用完成' % (round_idx + 1))
                    continue

                full_reply = msg.get('content') or ''
                break

            if not full_reply:
                full_reply = '任务执行完成（无文本输出）'

            # 收集产出物
            artifacts = _collect_artifacts(ctx)

            # 写入执行日志
            _write_task_log(ctx, full_reply, token_used)

            progress = 95
            ctx.report_progress(progress, 'summarizing', '结果汇总完成')

            # 构造 result_document
            result_doc = full_reply
            if artifacts:
                result_doc += '\n\n---\n产出文件:\n'
                for a in artifacts:
                    result_doc += '- %s\n' % a

            ctx.report_progress(100, 'submitting', '提交结果')

            elapsed = time.monotonic() - t_start
            logger.info('任务执行完成: task=%s type=%s token=%d len=%d 耗时=%.1fs',
                        ctx.task_id, ctx.task_type, token_used,
                        len(full_reply), elapsed)

            return TaskResult(
                result_document=result_doc,
                result_status='SUCCESS',
                token_used=token_used,
                artifacts=artifacts)

        except Exception as e:
            logger.exception('任务执行异常: %s', ctx.task_id)
            return TaskResult(
                result_document='任务执行失败: %s' % str(e)[:500],
                result_status='BLOCKED',
                token_used=token_used)

    # ── 代码任务：委托 SubagentProvider ──

    def _execute_code_task(self, ctx: TaskContext, app) -> TaskResult:
        """代码类任务 — 委托给 Qoder/Codex 子 Agent。"""
        token_used = 0
        t_start = time.monotonic()

        try:
            ctx.report_progress(5, 'received', '代码任务已接收')

            # 构造 SubagentRequest
            from agent_runtime.core.subagent import SubagentRequest
            task_text = ctx.spec_document or ctx.title
            if ctx.title and ctx.spec_document:
                task_text = '%s\n\n%s' % (ctx.title, ctx.spec_document)

            request = SubagentRequest(
                task=task_text,
                context={
                    'cwd': str(ctx.repo_docs_dir or ctx.task_workspace),
                    'instructions': (
                        '你是一个代码编写专家。请根据以下任务规格编写代码。\n'
                        '代码文件保存到: %s\n'
                        '中间工作文件保存到: %s'
                        % (ctx.repo_docs_dir, ctx.task_workspace)
                    ),
                },
                timeout_ms=300_000,  # 5 分钟超时
                provider=_select_code_provider(app),
            )

            ctx.report_progress(10, 'delegating', '委托给子 Agent 执行')

            # 异步执行子 Agent
            loop = asyncio.new_event_loop()
            try:
                result = loop.run_until_complete(
                    app.subagent_manager.execute(request))
            finally:
                loop.close()

            ctx.report_progress(90, 'collecting', '收集代码产出物')

            if result.success:
                artifacts = _collect_artifacts(ctx)
                _write_task_log(ctx, result.output, 0)

                result_doc = result.output or ''
                if artifacts:
                    result_doc += '\n\n---\n代码文件:\n'
                    for a in artifacts:
                        result_doc += '- %s\n' % a

                ctx.report_progress(100, 'submitting', '提交代码结果')

                elapsed = time.monotonic() - t_start
                logger.info('代码任务完成: task=%s provider=%s 耗时=%.1fs',
                            ctx.task_id, result.provider, elapsed)

                return TaskResult(
                    result_document=result_doc,
                    result_status='SUCCESS',
                    token_used=0,
                    artifacts=artifacts)
            else:
                ctx.report_progress(100, 'failed', '子 Agent 执行失败')
                return TaskResult(
                    result_document='代码任务失败: %s' % (result.error or '未知错误'),
                    result_status='BLOCKED',
                    token_used=0)

        except Exception as e:
            logger.exception('代码任务执行异常: %s', ctx.task_id)
            return TaskResult(
                result_document='代码任务执行失败: %s' % str(e)[:500],
                result_status='BLOCKED',
                token_used=token_used)


# ─────────────────────────────────────────
# 内部工具函数
# ─────────────────────────────────────────

def LLMClient_quick_estimate(text: str) -> int:
    """粗略估算 token（与 LLMClient._estimate_tokens 一致）。"""
    return max(len(text) // 3, 1)


def _parse_task_zero_json(text: str) -> list:
    """从 Task 0 返回文本中解析任务列表 JSON。

    支持三种策略：
    1. 纯 JSON 数组
    2. Markdown ```json ... ``` 代码块
    3. 文本中嵌入的 JSON 数组
    """
    if not text:
        return []

    stripped = text.strip()

    # 策略1: 直接解析
    try:
        data = json.loads(stripped)
        if isinstance(data, list):
            return _validate_task_list(data)
    except (json.JSONDecodeError, ValueError):
        pass

    # 策略2: 提取 ```json ... ``` 代码块
    json_blocks = re.findall(r'```(?:json)?\s*\n?(.*?)\n?```', stripped, re.DOTALL)
    for block in json_blocks:
        try:
            data = json.loads(block.strip())
            if isinstance(data, list):
                return _validate_task_list(data)
        except (json.JSONDecodeError, ValueError):
            continue

    # 策略3: 查找文本中的 JSON 数组
    bracket_start = stripped.find('[')
    if bracket_start >= 0:
        bracket_end = stripped.rfind(']')
        if bracket_end > bracket_start:
            try:
                data = json.loads(stripped[bracket_start:bracket_end + 1])
                if isinstance(data, list):
                    return _validate_task_list(data)
            except (json.JSONDecodeError, ValueError):
                pass

    logger.warning('Task 0 JSON 解析失败')
    return []


def _validate_task_list(tasks: list) -> list:
    """验证任务列表，过滤无效条目。"""
    valid = []
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if not t.get('title'):
            continue
        valid.append(t)
    return valid


def _format_task_zero_result(tasks_json: list) -> str:
    """将 Task 0 拆解结果格式化为 result_document。"""
    lines = ['## 任务拆解方案\n']
    for i, t in enumerate(tasks_json):
        title = t.get('title', '任务 %d' % (i + 1))
        desc = t.get('description', '')
        skills = ', '.join(t.get('required_skills', []))
        hours = t.get('estimated_hours', 0)
        depends = t.get('depends_on', [])
        role = t.get('suggested_role', '')
        agent_id = t.get('suggested_agent_id', '')
        tpl = t.get('template_ref', '')

        lines.append('### %d. %s' % (i + 1, title))
        if desc:
            lines.append(desc)
        lines.append('')
        info_parts = []
        if skills:
            info_parts.append('技能: %s' % skills)
        if hours:
            info_parts.append('预估: %dh' % hours)
        if role:
            info_parts.append('角色: %s' % role)
        if agent_id:
            info_parts.append('执行人: %s' % agent_id)
        if tpl:
            info_parts.append('模板: %s' % tpl)
        if depends:
            info_parts.append('依赖: %s' % depends)
        if info_parts:
            lines.append(' | '.join(info_parts))
        lines.append('')

    # 附上原始 JSON（供平台解析）
    lines.append('---\n')
    lines.append('```json')
    lines.append(json.dumps(tasks_json, ensure_ascii=False, indent=2))
    lines.append('```')

    return '\n'.join(lines)


def _select_code_provider(app) -> Optional[str]:
    """选择代码子 Agent provider。优先 Qoder，其次 Codex，兜底 in-process。"""
    providers = app.subagent_manager.providers
    if 'qoder' in providers:
        return 'qoder'
    if 'codex' in providers:
        return 'codex'
    if 'in-process' in providers:
        return 'in-process'
    return None


def _collect_artifacts(ctx: TaskContext) -> list:
    """收集任务工作空间中的产出文件。"""
    artifacts = []
    # 收集 repo_docs_dir 中的文件
    if ctx.repo_docs_dir and ctx.repo_docs_dir.exists():
        for f in ctx.repo_docs_dir.rglob('*'):
            if f.is_file() and not f.name.startswith('.'):
                artifacts.append(f)
    # 收集 task_workspace 中 artifacts/ 子目录的文件
    if ctx.task_workspace:
        art_dir = ctx.task_workspace / 'artifacts'
        if art_dir.exists():
            for f in art_dir.rglob('*'):
                if f.is_file():
                    artifacts.append(f)
        # 也收集根目录的 .md 文件（非草稿）
        for f in ctx.task_workspace.glob('*.md'):
            if f.name != 'draft.md' and f.name != 'task.log':
                artifacts.append(f)
    return artifacts


def _write_task_log(ctx: TaskContext, result: str, token_used: int):
    """写入任务执行日志。"""
    if not ctx.task_workspace:
        return
    log_file = ctx.task_workspace / 'task.log'
    try:
        from datetime import datetime
        with open(log_file, 'w', encoding='utf-8') as f:
            f.write('平台任务执行日志\n')
            f.write('=' * 40 + '\n')
            f.write('任务 ID: %s\n' % ctx.task_id)
            f.write('平台任务 ID: %s\n' % ctx.platform_task_id)
            f.write('标题: %s\n' % ctx.title)
            f.write('类型: %s\n' % ctx.task_type)
            f.write('创建时间: %s\n' % datetime.now().strftime('%Y-%m-%d %H:%M:%S'))
            f.write('工作目录: %s\n' % ctx.task_workspace)
            f.write('Token 消耗: %d\n' % token_used)
            f.write('=' * 40 + '\n\n')
            f.write('结果:\n')
            f.write(result[:5000] if result else '(无输出)')
    except Exception:
        logger.debug('写入任务日志失败', exc_info=True)
